import{_ as t,o as n,c as o,a2 as i}from"./chunks/framework.DpXDHk3d.js";const h=JSON.parse('{"title":"2.6 电与磁及电磁感应","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-6-dian-yu-ci-ji-dian-ci-gan-ying.md","filePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-6-dian-yu-ci-ji-dian-ci-gan-ying.md","lastUpdated":1793095197000}'),s={name:"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-6-dian-yu-ci-ji-dian-ci-gan-ying.md"};function l(r,a,e,g,c,p){return n(),o("div",null,[...a[0]||(a[0]=[i(`<h1 id="_2-6-电与磁及电磁感应" tabindex="-1">2.6 电与磁及电磁感应 <a class="header-anchor" href="#_2-6-电与磁及电磁感应" aria-label="Permalink to &quot;2.6 电与磁及电磁感应&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>&quot;电&quot;和&quot;磁&quot;是一家:电可以生磁,磁也可以生电。这两条规律催生了电动机、发电机、变压器、电磁铁、继电器等几乎所有重要的电气设备。这一节把&quot;电生磁、磁生电&quot;讲清楚——它是理解第 7 章变压器、第 8 章电动机的基础。</p><h2 id="一、磁的基本概念" tabindex="-1">一、磁的基本概念 <a class="header-anchor" href="#一、磁的基本概念" aria-label="Permalink to &quot;一、磁的基本概念&quot;">​</a></h2><ul><li><strong>磁体</strong>:有吸引铁、钴、镍能力的物体(磁铁、地球都是磁体)。</li><li><strong>磁极</strong>:磁体上磁性最强的两端,分<strong>N 极(北极)和 S 极(南极)</strong>。 <ul><li>规则:同名磁极相斥,异名磁极相吸。</li></ul></li><li><strong>磁场</strong>:磁体周围存在看不见、摸不着的特殊物质——磁场。</li><li><strong>磁感线</strong>:用来形象描述磁场的假想曲线: <ul><li>方向:在磁体<strong>外部,从 N 极出发回到 S 极</strong>;在磁体<strong>内部,从 S 极到 N 极</strong>,形成闭合曲线;</li><li>磁感线越密,磁场越强;磁感线是<strong>闭合的、不相交</strong>的。</li></ul></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   N ────────►  S      (磁体外部:从 N 到 S)</span></span>
<span class="line"><span>   ▲                 │</span></span>
<span class="line"><span>   └─────────────────┘   (内部:从 S 到 N,闭合)</span></span></code></pre></div><h2 id="二、电流的磁效应-电生磁" tabindex="-1">二、电流的磁效应:电生磁 <a class="header-anchor" href="#二、电流的磁效应-电生磁" aria-label="Permalink to &quot;二、电流的磁效应:电生磁&quot;">​</a></h2><p><strong>电流通过导体时,周围会产生磁场</strong>——这是丹麦物理学家<strong>奥斯特</strong>发现的,叫电流的磁效应。</p><ul><li>通电直导线周围产生磁场,磁感线是以导线为圆心的一圈圈同心圆;</li><li>电流方向与磁场方向的关系,用**右手螺旋定则(安培定则)**判断:右手握住导线,<strong>四指弯向电流方向,大拇指指向磁感线方向</strong>(或反向记忆)。</li></ul><blockquote><p>💡 通俗理解:电线一通电,周围就像围了一圈&quot;看不见的磁力&quot;,能把指南针吸得乱转。<strong>电流一停,磁场消失。</strong></p></blockquote><h2 id="三、电磁铁与电磁继电器" tabindex="-1">三、电磁铁与电磁继电器 <a class="header-anchor" href="#三、电磁铁与电磁继电器" aria-label="Permalink to &quot;三、电磁铁与电磁继电器&quot;">​</a></h2><p><strong>电磁铁</strong> = 通电螺线管 + 铁芯,电流通过时产生磁场,磁力把铁芯磁化,从而吸引衔铁。</p><ul><li>特点:<strong>电流通,有磁力;电流断,磁力消失</strong>——电一断,吸力立刻没了(这点和永久磁铁不同)。</li><li>应用:<strong>电磁继电器</strong>用&quot;小电流控制大电流&quot;——弱电流控制电磁铁通断,电磁铁再带动触点接通或断开主电路。这就是接触器、继电器的原理基础(第 5 章详讲)。</li></ul><h2 id="四、电磁感应-磁生电" tabindex="-1">四、电磁感应:磁生电 <a class="header-anchor" href="#四、电磁感应-磁生电" aria-label="Permalink to &quot;四、电磁感应:磁生电&quot;">​</a></h2><p><strong>电磁感应</strong>是英国物理学家<strong>法拉第</strong>发现的:</p><blockquote><p>当<strong>穿过闭合回路的磁通量发生变化</strong>时,回路中会产生<strong>感应电流</strong>;如果回路不闭合,则在两端产生<strong>感应电动势</strong>。</p></blockquote><p><strong>一句话</strong>:变化的磁,能生电。</p><p><strong>感应电动势的大小</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E = N · ΔΦ / Δt</span></span></code></pre></div><p>即与线圈匝数 N 和磁通变化快慢(ΔΦ/Δt)有关——<strong>磁通变化越快、线圈匝数越多,感应电动势越大</strong>。</p><blockquote><p>💡 <strong>水流类比</strong>:磁通变化就像&quot;水位突降&quot;,变化越猛,产生的水流(电流)越大。发电机、变压器靠的都是这个原理。</p></blockquote><p><strong>楞次定律</strong>:感应电流的方向,总是<strong>阻碍</strong>引起它的磁通变化。通俗记:<strong>&quot;来拒去留&quot;</strong>——磁通增了就想办法不让它增,减了就想办法不让它减。判断感应电流方向时用右手定则。</p><h2 id="五、自感与互感" tabindex="-1">五、自感与互感 <a class="header-anchor" href="#五、自感与互感" aria-label="Permalink to &quot;五、自感与互感&quot;">​</a></h2><ul><li><strong>自感</strong>:线圈自身电流变化时,在线圈内产生的感应电动势,阻碍电流的变化。</li><li><strong>互感</strong>:一个线圈中电流变化,在<strong>邻近另一个线圈</strong>中产生感应电动势。</li></ul><blockquote><p>⚠️ <strong>重点</strong>:<strong>互感是变压器的工作原理</strong>——初级线圈的电流变化,通过共同的铁芯磁路,在次级线圈中感应出电压。所以<strong>变压器只能变交流,不能变直流</strong>(直流电流不变化,磁通不变,不产生感应)。这点第 7 章会反复用到。</p></blockquote><h2 id="六、电与磁的完整关系图" tabindex="-1">六、电与磁的完整关系图 <a class="header-anchor" href="#六、电与磁的完整关系图" aria-label="Permalink to &quot;六、电与磁的完整关系图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>通电导线 ──产生──► 磁场(电流的磁效应)      → 电磁铁、继电器</span></span>
<span class="line"><span>磁场变化 ──产生──► 感应电动势(电磁感应)      → 发电机、变压器</span></span>
<span class="line"><span>     两者都由&quot;变化的电流/磁通&quot;联系在一起</span></span></code></pre></div><h2 id="七、考点提示" tabindex="-1">七、考点提示 <a class="header-anchor" href="#七、考点提示" aria-label="Permalink to &quot;七、考点提示&quot;">​</a></h2><ul><li>✅ 磁感线在磁体外部从 <strong>N 极到 S 极</strong>,是<strong>闭合曲线</strong>。</li><li>✅ 电流的磁效应:通电导线周围产生磁场(奥斯特)。</li><li>✅ 电磁感应:磁通量变化产生感应电动势(法拉第);<strong>变压器靠互感原理,只能变交流</strong>。</li><li>✅ 电磁铁&quot;有电有磁力、断电失磁力&quot;,用于电磁继电器控制大电流。</li><li>⚠️ 易混点:电生磁(奥斯特/电流的磁效应)和磁生电(法拉第/电磁感应)方向相反,别记反。</li></ul><h2 id="八、本节小结" tabindex="-1">八、本节小结 <a class="header-anchor" href="#八、本节小结" aria-label="Permalink to &quot;八、本节小结&quot;">​</a></h2><ul><li>磁体有 N、S 两极,磁感线从 N 到 S(外部)闭合。</li><li>电流的磁效应:电生磁 → 电磁铁、继电器。</li><li>电磁感应:磁生电 → 发电机、变压器。</li><li>变压器靠互感,只能变换交流,不能变换直流。</li></ul><h2 id="九、自测练习" tabindex="-1">九、自测练习 <a class="header-anchor" href="#九、自测练习" aria-label="Permalink to &quot;九、自测练习&quot;">​</a></h2><ol><li>(判断)磁感线在磁体外部是从 N 极指向 S 极的。( )</li><li>(单选)电流通过导体时,导体周围会产生(),这种现象称为电流的磁效应。 A. 电场　B. 磁场　C. 声场　D. 电磁波</li><li>(判断)电磁感应是指磁通量发生变化时,回路中产生感应电动势的现象。( )</li><li>(单选)变压器是利用()原理工作的。 A. 电流的热效应　B. 电磁感应(互感)　C. 电流的磁效应　D. 静电感应</li><li>(判断)变压器可以变换直流电压。( )</li><li>(单选)同名磁极相互()。 A. 吸引　B. 排斥　C. 无作用　D. 不确定</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。磁感线在磁体外部从 N 极指向 S 极。</li><li><strong>B</strong>。通电导线周围产生磁场,即电流的磁效应。</li><li><strong>√</strong>。电磁感应定义正确。</li><li><strong>B</strong>。变压器靠互感(电磁感应)原理工作。</li><li><strong>×</strong>。直流电不变化,磁通不变,不能产生感应——变压器只能变换交流。</li><li><strong>B</strong>。同名磁极相斥,异名磁极相吸。</li></ol></details>`,34)])])}const d=t(s,[["render",l]]);export{h as __pageData,d as default};
